6	@@ -0,0 +1,118 @@
7	+import React from 'react';
8	+import type { Meta, StoryObj } from '@storybook/react-webpack5';
9	+import { expect, within } from 'storybook/test';
10	+import { Box } from '@chakra-ui/react';
11	+import { ZimmTable } from './index';
12	+
13	+const CM_COLUMNS = ['SIZE', 'XS', 'S', 'M', 'L', 'XL'];
14	+
15	+const CM_ROWS = [
16	+  { label: 'Bust', cells: [76, 81, 86, 91, 96] },
17	+  { label: 'Waist', cells: [60, 65, 70, 75, 80] },
18	+  { label: 'Hips', cells: [84, 89, 94, 99, 104] },
19	+  { label: 'Length', cells: [130, 131, 132, 133, 134] },
20	+];
21	+
22	+const INCH_ROWS = [
23	+  { label: 'Bust', cells: [29.9, 31.9, 33.9, 35.8, 37.8] },
24	+  { label: 'Waist', cells: [23.6, 25.6, 27.6, 29.5, 31.5] },
25	+  { label: 'Hips', cells: [33.1, 35.0, 37.0, 39.0, 40.9] },
26	+  { label: 'Length', cells: [51.2, 51.6, 52.0, 52.4, 52.8] },
27	+];
28	+
29	+const LABELLESS_ROWS = [
30	+  { label: '', isHeader: true, convertible: false, cells: ['OSFA'], spans: [3] },
31	+  { label: '', isHeader: false, convertible: true, cells: ['56–59'], spans: [3] },
32	+  { label: '', isHeader: true, convertible: false, cells: ['S/M', 'M/L'], spans: [2, 1] },
33	+  { label: '', isHeader: false, convertible: true, cells: ['56–57', '58–59'], spans: [2, 1] },
34	+  { label: '', isHeader: true, convertible: false, cells: ['S', 'M', 'L'], spans: [1, 1, 1] },
35	+  { label: '', isHeader: false, convertible: true, cells: ['55', '57', '59'], spans: [1, 1, 1] },
36	+];
37	+
38	+const meta: Meta<typeof ZimmTable> = {
39	+  title: 'Elements/ZimmTable',
40	+  component: ZimmTable,
41	+  decorators: [
42	+    (Story: React.ComponentType) => (
43	+      <Box width="522px" padding="var(--zimm-scale-m)">
44	+        <Story />
45	+      </Box>
46	+    ),
47	+  ],
48	+};
49	+export default meta;
50	+
51	+type Story = StoryObj<typeof ZimmTable>;
52	+
53	+export const Default: Story = {
54	+  name: 'Default — size measurements in cm',
55	+  args: {
56	+    columns: CM_COLUMNS,
57	+    rows: CM_ROWS,
58	+  },
59	+  play: async ({ canvasElement }) => {
60	+    const canvas = within(canvasElement);
61	+    // Column headers render
62	+    await expect(canvas.getByRole('columnheader', { name: 'XS' })).toBeInTheDocument();
63	+    // Row label renders
64	+    await expect(canvas.getByRole('cell', { name: 'Bust' })).toBeInTheDocument();
65	+    // Cell value renders
66	+    await expect(canvas.getByRole('cell', { name: '76' })).toBeInTheDocument();
67	+  },
68	+};
69	+
70	+export const MeasurementsInCm: Story = {
71	+  name: 'Body measurements — cm',
72	+  args: {
73	+    columns: CM_COLUMNS,
74	+    rows: CM_ROWS,
75	+  },
76	+};
77	+
78	+export const MeasurementsInInch: Story = {
79	+  name: 'Body measurements — inch (converted values)',
80	+  args: {
81	+    columns: CM_COLUMNS,
82	+    rows: INCH_ROWS,
83	+  },
84	+};
85	+
86	+export const Labelless: Story = {
87	+  name: 'Labelless — grouped rows without label column',
88	+  args: {
89	+    columns: [],
90	+    labelless: true,
91	+    rows: LABELLESS_ROWS,
92	+  },
93	+};
94	+
95	+export const LabellessBordered: Story = {
96	+  name: 'Labelless + bordered — hat table with vertical dividers',
97	+  args: {
98	+    columns: [],
99	+    labelless: true,
100	+    bordered: true,
101	+    rows: LABELLESS_ROWS,
102	+  },
103	+};
104	+
105	+export const WithSubColumns: Story = {
106	+  name: 'Grouped sub-columns — gloves table',
107	+  args: {
108	+    columns: ['SIZE', 'SHORT GLOVES', 'LONG GLOVES'],
109	+    columnSpan: 2,
110	+    subColumns: ['S/M', 'M/L'],
111	+    rows: [
112	+      { label: 'Length', cells: [26.3, 27.4, 61.5, 62.6] },
113	+      { label: 'Cuff Opening', cells: [20.8, 26.1, 24.2, 26.1] },
114	+    ],
115	+  },
116	+};
117	+
118	+export const Empty: Story = {
119	+  name: 'Empty — no rows',
120	+  args: {
121	+    columns: CM_COLUMNS,
122	+    rows: [],
123	+  },
124	+};
