130	@@ -0,0 +1,82 @@
131	+import React from 'react';
132	+import { render, screen } from '@testing-library/react';
133	+import { describe, test, expect } from 'vitest';
134	+import { ZimmTable } from './index';
135	+
136	+describe('ZimmTable — standard table', () => {
137	+  test('renders column headers in thead', () => {
138	+    const { container } = render(<ZimmTable columns={['SIZE', 'XS', 'S', 'M']} rows={[]} />);
139	+    expect(screen.getByText('SIZE')).toBeInTheDocument();
140	+    expect(screen.getByText('XS')).toBeInTheDocument();
141	+    expect(container.querySelectorAll('thead th')).toHaveLength(4);
142	+  });
143	+
144	+  test('renders row label and cell values', () => {
145	+    render(<ZimmTable columns={['SIZE', 'XS', 'S']} rows={[{ label: 'Bust', cells: [76, 81] }]} />);
146	+    expect(screen.getByText('Bust')).toBeInTheDocument();
147	+    expect(screen.getByText('76')).toBeInTheDocument();
148	+    expect(screen.getByText('81')).toBeInTheDocument();
149	+  });
150	+
151	+  test('renders subColumns as a second header row', () => {
152	+    render(
153	+      <ZimmTable
154	+        columns={['', 'SHORT GLOVES', 'LONG GLOVES']}
155	+        columnSpan={2}
156	+        subColumns={['S/M', 'M/L']}
157	+        rows={[{ label: 'Length', cells: [26, 27, 61, 62] }]}
158	+      />,
159	+    );
160	+    // S/M and M/L appear once per main column group (2 groups × 2 subcolumns)
161	+    expect(screen.getAllByText('S/M')).toHaveLength(2);
162	+    expect(screen.getAllByText('M/L')).toHaveLength(2);
163	+  });
164	+
165	+  test('renders empty rows without crashing', () => {
166	+    render(<ZimmTable columns={['SIZE', 'XS']} rows={[]} />);
167	+    expect(screen.getByText('SIZE')).toBeInTheDocument();
168	+  });
169	+});
170	+
171	+describe('ZimmTable — labelless table', () => {
172	+  const LABELLESS_ROWS = [
173	+    { label: '', isHeader: true, convertible: false, cells: ['OSFA'], spans: [3] },
174	+    { label: '', isHeader: false, convertible: true, cells: ['56–59'], spans: [3] },
175	+  ];
176	+
177	+  test('renders isHeader rows as th and value rows as td', () => {
178	+    const { container } = render(<ZimmTable columns={[]} labelless rows={LABELLESS_ROWS} />);
179	+    // isHeader row → th; value row → td
180	+    expect(container.querySelectorAll('th')).toHaveLength(1);
181	+    expect(container.querySelectorAll('td')).toHaveLength(1);
182	+  });
183	+
184	+  test('renders cell values', () => {
185	+    render(<ZimmTable columns={[]} labelless rows={LABELLESS_ROWS} />);
186	+    expect(screen.getByText('OSFA')).toBeInTheDocument();
187	+    expect(screen.getByText('56–59')).toBeInTheDocument();
188	+  });
189	+});
190	+
191	+describe('ZimmTable — labelless + bordered table', () => {
192	+  const BORDERED_ROWS = [
193	+    { label: '', isHeader: true, convertible: false, cells: ['S/M', 'M/L'], spans: [1, 1] },
194	+    { label: '', isHeader: false, convertible: true, cells: ['56', '58'], spans: [1, 1] },
195	+    { label: '', isHeader: true, convertible: false, cells: ['S', 'M', 'L'], spans: [1, 1, 1] },
196	+    { label: '', isHeader: false, convertible: true, cells: ['55', '57', '59'], spans: [1, 1, 1] },
197	+  ];
198	+
199	+  test('renders all groups without crashing', () => {
200	+    render(<ZimmTable columns={[]} labelless bordered rows={BORDERED_ROWS} />);
201	+    expect(screen.getByText('S/M')).toBeInTheDocument();
202	+    expect(screen.getByText('56')).toBeInTheDocument();
203	+    expect(screen.getByText('S')).toBeInTheDocument();
204	+    expect(screen.getByText('55')).toBeInTheDocument();
205	+  });
206	+
207	+  test('inserts a spacer row between groups', () => {
208	+    const { container } = render(<ZimmTable columns={[]} labelless bordered rows={BORDERED_ROWS} />);
209	+    // 2 groups × (1 header + 1 value) rows = 4 data rows + 1 spacer between groups = 5 tr total
210	+    expect(container.querySelectorAll('tr')).toHaveLength(5);
211	+  });
212	+});
213	diff --git a/overrides/app/components/ui-kits/atoms/zimmTable/index.tsx b/overrides/app/components/ui-kits/atoms/zimmTable/index.tsx
214	new file mode 100644
215	index 00000000..20144245
216	--- /dev/null
217	+++ b/overrides/app/components/ui-kits/atoms/zimmTable/index.tsx
218	@@ -0,0 +1,231 @@
219	+import React from 'react';
220	+import { chakra, useMultiStyleConfig, VisuallyHidden } from '@chakra-ui/react';
221	+import { BORDER_SECONDARY, BORDER_FOCUS } from './zimmTable.css';
222	+
223	+const ZIMM_TABLE_RECIPE = 'ZimmTable';
224	+
225	+export type ZimmTableRow = {
226	+  label: string;
227	+  cells: readonly (string | number)[];
228	+  spans?: readonly number[];
229	+  /** When true, renders this row as a bold group sub-header (labelless mode only). */
230	+  isHeader?: boolean;
231	+};
232	+
233	+export type ZimmTableProps = {
234	+  columns: readonly string[];
235	+  /** Sub-columns per main column. When > 1, main column headers span this many cells. */
236	+  columnSpan?: number;
237	+  /**
238	+   * Sub-column labels rendered in a second thead row. Each label repeats once per main
239	+   * column group (excluding the label column). The label column spans both header rows
240	+   * via rowSpan=2. Used for the gloves table (S/M | M/L repeating under SHORT/LONG GLOVES).
241	+   */
242	+  subColumns?: readonly string[];
243	+  rows: readonly ZimmTableRow[];
244	+  /**
245	+   * Omits the label column and thead entirely. Rows alternate between isHeader=true
246	+   * (bold group header rendered as th) and isHeader=false (measurement values).
247	+   * Used for the hat table's 3-level grouped layout.
248	+   */
249	+  labelless?: boolean;
250	+  /**
251	+   * Used with labelless: renders vertical cell dividers (borderLeft on non-first cells)
252	+   * instead of row striping. Header rows get a dark bottom border; value rows get a light one.
253	+   */
254	+  bordered?: boolean;
255	+};
256	+
257	+/**
258	+ * Generic data table atom for the Size Guide drawer (SFCC-102).
259	+ * Caller is responsible for passing display-ready values — unit conversion
260	+ * happens upstream in SizeGuideContent, not here.
261	+ *
262	+ * columnSpan enables grouped headers (e.g. belt tables where XS/S spans 2 data columns).
263	+ * row.spans controls per-cell colspan for merged rows. Omitting both fields preserves the
264	+ * standard single-level layout used by clothing/shoe tables.
265	+ */
266	+export const ZimmTable = ({
267	+  columns,
268	+  columnSpan = 1,
269	+  subColumns,
270	+  rows,
271	+  labelless = false,
272	+  bordered = false,
273	+}: ZimmTableProps) => {
274	+  const variant = labelless && bordered ? 'bordered' : labelless ? 'labelless' : 'standard';
275	+  const styles = useMultiStyleConfig(ZIMM_TABLE_RECIPE, { variant });
276	+
277	+  if (labelless && bordered) {
278	+    // Pair consecutive rows into [headerRow, valueRow] groups, separated by a visual gap.
279	+    const groups: ZimmTableRow[][] = [];
280	+    for (let i = 0; i < rows.length; i += 2) groups.push(rows.slice(i, i + 2));
281	+    // Derive total column count from the maximum span sum across all rows.
282	+    const totalCols = Math.max(...rows.map((row) => (row.spans ?? row.cells.map(() => 1)).reduce((a, b) => a + b, 0)));
283	+    return (
284	+      <chakra.table __css={styles.table}>
285	+        <chakra.colgroup>
286	+          {Array.from({ length: totalCols }).map((_, i) => (
287	+            <chakra.col key={i} width={`${(100 / totalCols).toFixed(4)}%`} />
288	+          ))}
289	+        </chakra.colgroup>
290	+        <chakra.tbody>
291	+          {groups.map((group, gi) => (
292	+            <React.Fragment key={gi}>
293	+              {gi > 0 && (
294	+                <chakra.tr>
295	+                  <chakra.td __css={styles.spacerTd} colSpan={totalCols} />
296	+                </chakra.tr>
297	+              )}
298	+              {group.map((row, ri) =>
299	+                row.isHeader ? (
300	+                  <chakra.tr key={ri}>
301	+                    {row.cells.map((cell, j) => (
302	+                      <chakra.th
303	+                        key={j}
304	+                        __css={styles.th}
305	+                        colSpan={row.spans?.[j] ?? 1}
306	+                        textAlign="center"
307	+                        borderBottom={BORDER_FOCUS}
308	+                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
309	+                      >
310	+                        {cell}
311	+                      </chakra.th>
312	+                    ))}
313	+                  </chakra.tr>
314	+                ) : (
315	+                  <chakra.tr key={ri}>
316	+                    {row.cells.map((cell, j) => (
317	+                      <chakra.td
318	+                        key={j}
319	+                        __css={styles.td}
320	+                        colSpan={row.spans?.[j] ?? 1}
321	+                        textAlign="center"
322	+                        borderBottom={BORDER_SECONDARY}
323	+                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
324	+                      >
325	+                        {cell}
326	+                      </chakra.td>
327	+                    ))}
328	+                  </chakra.tr>
329	+                ),
330	+              )}
331	+            </React.Fragment>
332	+          ))}
333	+        </chakra.tbody>
334	+      </chakra.table>
335	+    );
336	+  }
337	+
338	+  if (labelless) {
339	+    return (
340	+      <chakra.table __css={styles.table}>
341	+        <chakra.tbody>
342	+          {rows.map((row, i) =>
343	+            row.isHeader ? (
344	+              <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
345	+                {row.cells.map((cell, j) => (
346	+                  <chakra.th
347	+                    key={j}
348	+                    __css={styles.th}
349	+                    colSpan={row.spans?.[j] ?? 1}
350	+                    textAlign="center"
351	+                    borderBottom={BORDER_SECONDARY}
352	+                  >
353	+                    {cell}
354	+                  </chakra.th>
355	+                ))}
356	+              </chakra.tr>
357	+            ) : (
358	+              <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
359	+                {row.cells.map((cell, j) => (
360	+                  <chakra.td
361	+                    key={j}
362	+                    __css={styles.td}
363	+                    colSpan={row.spans?.[j] ?? 1}
364	+                    textAlign="center"
365	+                    borderBottom={BORDER_SECONDARY}
366	+                  >
367	+                    {cell}
368	+                  </chakra.td>
369	+                ))}
370	+              </chakra.tr>
371	+            ),
372	+          )}
373	+        </chakra.tbody>
374	+      </chakra.table>
375	+    );
376	+  }
377	+
378	+  return (
379	+    <chakra.table __css={styles.table}>
380	+      <chakra.thead>
381	+        <chakra.tr>
382	+          {columns.map((col, j) => (
383	+            <chakra.th
384	+              key={j}
385	+              __css={styles.th}
386	+              colSpan={j === 0 ? 1 : columnSpan}
387	+              rowSpan={subColumns && subColumns.length > 0 && j === 0 ? 2 : 1}
388	+              textAlign={j === 0 ? 'left' : 'center'}
389	+              verticalAlign={subColumns && subColumns.length > 0 && j === 0 ? 'middle' : undefined}
390	+              borderBottom={subColumns && subColumns.length > 0 && j > 0 ? 'none' : BORDER_FOCUS}
391	+              borderRight={columnSpan > 1 && j > 0 && j < columns.length - 1 ? BORDER_SECONDARY : undefined}
392	+              position={!col ? 'relative' : undefined}
393	+            >
394	+              {/* Visually-hidden text satisfies axe empty-table-header on the empty corner cell. */}
395	+              {!col && <VisuallyHidden>Category</VisuallyHidden>}
396	+              {col}
397	+            </chakra.th>
398	+          ))}
399	+        </chakra.tr>
400	+        {subColumns && subColumns.length > 0 && (
401	+          <chakra.tr>
402	+            {columns.slice(1).flatMap((_, colIdx) =>
403	+              subColumns.map((sub, subIdx) => (
404	+                <chakra.th
405	+                  key={`${colIdx}-${subIdx}`}
406	+                  __css={styles.th}
407	+                  textAlign="center"
408	+                  borderBottom={BORDER_FOCUS}
409	+                  borderRight={
410	+                    colIdx < columns.slice(1).length - 1 && subIdx === subColumns.length - 1
411	+                      ? BORDER_SECONDARY
412	+                      : undefined
413	+                  }
414	+                >
415	+                  {sub}
416	+                </chakra.th>
417	+              )),
418	+            )}
419	+          </chakra.tr>
420	+        )}
421	+      </chakra.thead>
422	+      <chakra.tbody>
423	+        {rows.map((row, i) => (
424	+          <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
425	+            <chakra.td __css={styles.labelTd} borderBottom={BORDER_SECONDARY}>
426	+              {row.label}
427	+            </chakra.td>
428	+            {row.cells.map((cell, j) => {
429	+              const hasGroupRightBorder =
430	+                columnSpan > 1 && j < row.cells.length - 1 && (row.spans ? true : (j + 1) % columnSpan === 0);
431	+              return (
432	+                <chakra.td
433	+                  key={j}
434	+                  __css={styles.td}
435	+                  colSpan={row.spans?.[j] ?? 1}
436	+                  textAlign="center"
437	+                  borderBottom={BORDER_SECONDARY}
438	+                  borderRight={hasGroupRightBorder ? BORDER_SECONDARY : undefined}
439	+                >
440	+                  {cell}
441	+                </chakra.td>
442	+              );
443	+            })}
444	+          </chakra.tr>
445	+        ))}
446	+      </chakra.tbody>
447	+    </chakra.table>
448	+  );
449	+};
450	diff --git a/overrides/app/components/ui-kits/atoms/zimmTable/zimmTable.css.ts b/overrides/app/components/ui-kits/atoms/zimmTable/zimmTable.css.ts
451	new file mode 100644
452	index 00000000..39e30d1e
453	--- /dev/null
454	+++ b/overrides/app/components/ui-kits/atoms/zimmTable/zimmTable.css.ts
455	@@ -0,0 +1,88 @@
456	+const MIN_COL_WIDTH = 'calc(var(--zimm-scale-4xl) + var(--zimm-scale-m))';
457	+
458	+/** Reused as Chakra style prop values in index.tsx for conditional border logic. */
459	+export const BORDER_SECONDARY = `var(--zimm-border-width-default) solid var(--zimm-color-border-secondary)`;
460	+export const BORDER_FOCUS = `var(--zimm-border-width-default) solid var(--zimm-color-border-focus)`;
461	+
462	+/**
463	+ * Recipe for the ZimmTable data table atom (SFCC-102).
464	+ *
465	+ * Three variants mirror the three render branches in index.tsx:
466	+ *   standard  — labelled table with column headers and a row-label column
467	+ *   labelless — groups of isHeader/value rows, no thead, stripe background
468	+ *   bordered  — labelless + fixed-width columns, vertical cell dividers, group spacers
469	+ *
470	+ * Static base styles (text, colour, horizontal padding) live here; conditional styles
471	+ * (borderBottom, borderRight, textAlign, colSpan, row bg) are applied as direct Chakra
472	+ * props in the component so branching logic stays in JSX.
473	+ */
474	+export const ZimmTable = {
475	+  parts: ['table', 'th', 'td', 'labelTd', 'spacerTd'],
476	+  baseStyle: {
477	+    table: {
478	+      width: '100%',
479	+      borderCollapse: 'collapse',
480	+      // auto is the correct default for standard and labelless; bordered overrides to fixed.
481	+      tableLayout: 'auto',
482	+    },
483	+    // Shared header cell base: text style, colour, horizontal padding, nowrap.
484	+    // Vertical padding and textAlign differ by variant/column — applied as direct props.
485	+    th: {
486	+      textStyle: 'navigation',
487	+      color: 'var(--zimm-color-text-default)',
488	+      paddingX: 'var(--zimm-scale-2xs)',
489	+      whiteSpace: 'nowrap',
490	+    },
491	+    // Shared data cell base: text style, colour, horizontal padding.
492	+    // Vertical padding, textAlign, and minWidth differ by variant/role — applied as direct props.
493	+    td: {
494	+      textStyle: 'caption',
495	+      color: 'var(--zimm-color-text-default)',
496	+      paddingX: 'var(--zimm-scale-2xs)',
497	+    },
498	+    // Label column cell in standard mode: always left-aligned with full vertical padding and
499	+    // a minimum width to prevent the label column from collapsing under narrow viewports.
500	+    labelTd: {
501	+      textStyle: 'caption',
502	+      color: 'var(--zimm-color-text-default)',
503	+      textAlign: 'left',
504	+      paddingX: 'var(--zimm-scale-2xs)',
505	+      paddingY: 'var(--zimm-scale-xl)',
506	+      minWidth: MIN_COL_WIDTH,
507	+    },
508	+    // Spacer row inserted between groups in labelless+bordered mode.
509	+    // border:'none' prevents the collapsed border from bleeding through.
510	+    spacerTd: {
511	+      height: 'var(--zimm-scale-xl)',
512	+      padding: 0,
513	+      border: 'none',
514	+    },
