1786	+type Unit = 'cm' | 'inch';
1787	+
1788	+// Mirrors foundation/gridSystem breakpoints.md (768px = 48em). Media queries cannot consume
1789	+// CSS vars, so this is the one deliberate exception to the var(--zimm-*) convention (css.md > Tokens).
1790	+const TABLET_MIN_WIDTH = '48em';
