1794	+export const convertCm = (n: number) => Math.round(n * CM_TO_INCH * 10) / 10;
1795	+
1796	+/**
1797	+ * Converts a single cell text value from CM to inches when the unit is 'inch'.
1798	+ * Handles plain numeric strings (e.g. "76") and en-dash/hyphen ranges (e.g. "86–90").
1799	+ * Non-numeric strings (e.g. "AU 6", "XS") are returned unchanged.
1800	+ */
1801	+export const convertCellText = (text: string, unit: Unit): string => {
1802	+  if (unit !== 'inch') return text;
1803	+  // Multi-line stacked values (joined by extractCellText) — convert each line independently.
1804	+  if (text.includes('\n'))
1805	+    return text
1806	+      .split('\n')
1807	+      .map((line) => convertCellText(line, unit))
1808	+      .join('\n');
1809	+  const trimmed = text.trim();
1810	+  // Strip optional trailing 'cm' unit label (e.g. "56–59cm", "56 - 59 cm") so editors can
1811	+  // annotate cells with the unit without breaking numeric detection.
1812	+  const hasCmSuffix = /\s*cm$/i.test(trimmed);
1813	+  const stripped = hasCmSuffix ? trimmed.replace(/\s*cm$/i, '').trim() : trimmed;
1814	+  const rangeMatch = stripped.match(/^(\d+(?:\.\d+)?)\s*[–-]\s*(\d+(?:\.\d+)?)$/);
1815	+  if (rangeMatch) {
1816	+    const converted = `${convertCm(parseFloat(rangeMatch[1]))}–${convertCm(parseFloat(rangeMatch[2]))}`;
1817	+    return hasCmSuffix ? `${converted} in` : converted;
1818	+  }
1819	+  if (/^\d+(?:\.\d+)?$/.test(stripped)) {
1820	+    const converted = String(convertCm(Number(stripped)));
1821	+    return hasCmSuffix ? `${converted} in` : converted;
1822	+  }
1823	+  return text;
1824	+};
1825	+
1826	+/** Recursively extracts plain text from a Rich Text node tree. */
1827	+const extractText = (node: ContentfulRichTextNode): string => {
1828	+  if (node.nodeType === 'text') return node.value ?? '';
1829	+  return (node.content ?? []).map(extractText).join('');
1830	+};
1831	+
1832	+/**
1833	+ * Extracts display text from a table cell node.
1834	+ * Multiple paragraph children (Contentful stacked values) are joined with '\n'
1835	+ * so they render as separate lines when the cell has white-space: pre-line.
1836	+ */
1837	+const extractCellText = (node: ContentfulRichTextNode): string => {
1838	+  if (node.nodeType === 'text') return node.value ?? '';
1839	+  const children = node.content ?? [];
1840	+  const paragraphs = children.filter((c) => c.nodeType === 'paragraph');
1841	+  if (paragraphs.length > 1) {
1842	+    return paragraphs
1843	+      .map(extractText)
1844	+      .filter((t) => t.trim())
1845	+      .join('\n');
1846	+  }
1847	+  return extractText(node);
1848	+};
1849	+
1850	+/** Returns true if the Rich Text document contains at least one table node. */
1851	+const hasTableNode = (doc: ContentfulRichText): boolean => doc.content.some((n) => n.nodeType === 'table');
1852	+
1853	+/**
1854	+ * Returns true when a table should use the centered grouped layout (Figma "Layout 3").
1855	+ *
1856	+ * Two cases trigger this:
1857	+ * 1. Multiple header rows — the whole table alternates [header, value] pairs in one node.
1858	+ * 2. Non-empty first header cell — standard size-guide tables always have an empty first
1859	+ *    header cell (the label column has no heading). When the first header cell contains
1860	+ *    text (e.g. "OSFA", "S/M") it means all columns are equal-width data, not label+data.
1861	+ *    This covers the case where the rich text contains multiple separate small tables
1862	+ *    (one per group), each with only one header row.
1863	+ *
1864	+ * Uses `every` (not `some`) so a mixed row — where only the first cell is a header cell
1865	+ * (Contentful's "header column" option) — is not misclassified as a header row.
1866	+ */
1867	+
1868	+/** True when every cell in a row is a table-header-cell (i.e. a true header row). */
1869	+const isHeaderRow = (row: ContentfulRichTextNode): boolean => {
1870	+  const cells = row.content ?? [];
1871	+  return cells.length > 0 && cells.every((c) => c.nodeType === 'table-header-cell');
1872	+};
1873	+
1874	+export const isGroupedTableNode = (node: ContentfulRichTextNode): boolean => {
1875	+  const rows = (node.content ?? []).filter((r) => r.nodeType === 'table-row');
1876	+  const headerRows = rows.filter(isHeaderRow);
1877	+  if (headerRows.length > 1) return true;
1878	+  const firstHeader = headerRows[0];
1879	+  if (!firstHeader) return false;
1880	+  const firstCellText = extractText((firstHeader.content ?? [])[0] ?? { nodeType: 'text', value: '' }).trim();
1881	+  // Grouped layout (Figma Layout 3) has a non-empty first header cell AND exactly one body row
1882	+  // per sub-table. Standard multi-row tables (e.g. Rings, Cuff Bracelets) have a non-empty
1883	+  // first header cell too — the body-row count is what distinguishes them.
1884	+  const bodyRowCount = rows.length - headerRows.length;
1885	+  return firstCellText !== '' && bodyRowCount === 1;
1886	+};
1887	+
1888	+/**
1889	+ * Renders a Figma "Layout 3" grouped size table.
1890	+ *
1891	+ * Each pair of consecutive rows (header + value) forms one group, rendered as an
1892	+ * independent semantic <table> so screen readers associate header cells with their data
1893	+ * cells. Columns share width equally via the browser's default table layout — each table
1894	+ * has a consistent column count within its rows, so no colspan arithmetic is needed even
1895	+ * though different groups have different counts (OSFA=1, S/M+M/L=2, S+M+L=3).
1896	+ *
1897	+ * When the rich text contains separate table nodes per group (the Contentful authoring
1898	+ * pattern), each call to GroupedSizeTable handles one table node (one group). The outer
1899	+ * renderRichText VStack provides spacing between tables in that case, and the inner VStack
