1901	+ * (alternating header/value rows), the inner VStack provides the inter-group gap.
1902	+ */
1903	+const GroupedSizeTable = ({ node, unit }: { node: ContentfulRichTextNode; unit: Unit }) => {
1904	+  const allRows = (node.content ?? []).filter((r) => r.nodeType === 'table-row');
1905	+  const groups: ContentfulRichTextNode[][] = [];
1906	+  for (let i = 0; i < allRows.length; i += 2) groups.push(allRows.slice(i, i + 2));
1907	+
1908	+  return (
1909	+    <VStack align="stretch" spacing="var(--zimm-scale-xl)" width="100%">
1910	+      {groups.map((group, gi) => {
1911	+        const groupHeaderRows = group.filter(isHeaderRow);
1912	+        const groupBodyRows = group.filter((r) => !isHeaderRow(r));
1913	+        return (
1914	+          <chakra.table key={gi} width="100%" sx={{ borderCollapse: 'collapse', 'td, th': { whiteSpace: 'pre-line' } }}>
