2	import { getContentfulConfig } from '../config/contentful';
3	import type { ContentfulAsset } from '../types/contentful';
4	
5	type ContentfulLink = {
6	  sys: {
7	    type: 'Link';
8	    linkType: 'Asset' | 'Entry';
9	    id: string;
10	  };
11	};
12	
13	type ContentfulRawEntry = {
14	  sys: { id: string; [key: string]: unknown };
15	  fields: Record<string, ContentfulLink | ContentfulAsset | unknown>;
16	  [key: string]: unknown;
17	};
18	
19	type ContentfulEntriesResponse = {
20	  items: ContentfulRawEntry[];
21	  includes?: {
22	    Asset?: ContentfulAsset[];
23	    Entry?: ContentfulRawEntry[];
24	  };
25	};
