27	// Exported (alongside buildContentfulUrl/resolveLinkedAssets below) purely so they can be
28	// unit-tested directly as pure functions, the same way footer/index.tsx exports scopeToRegion —
29	// not part of this module's intended public surface for other callers.
30	//
31	// Throws rather than returning a nullable config so every caller's existing try/catch
32	// (which already converts a thrown Error into `error` state) handles the missing-config
33	// case for free, instead of each hook duplicating its own early-return branch.
34	export const getValidatedContentfulConfig = () => {
35	  const config = getContentfulConfig();
36	  if (!config.spaceId || !config.accessToken) {
37	    throw new Error('Contentful configuration missing');
38	  }
39	  return config;
40	};
41	
42	export const buildContentfulUrl = (
43	  query: string,
44	  config: ReturnType<typeof getContentfulConfig>,
45	  preview: boolean,
46	  locale?: string,
47	  // include=2 is the minimum depth that resolves linked assets one level below a linked entry.
48	  // Pass 3 when a fetch chain is 3 hops deep (e.g. sizeGuide → sizeGuideTable → image → asset).
49	  include = 2,
50	): string => {
51	  const { spaceId, accessToken, previewAccessToken, environment } = config;
52	  const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
53	  const token = preview ? previewAccessToken : accessToken;
54	  const localeParam = locale ? `&locale=${encodeURIComponent(locale)}` : '';
55	  return `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?${query}&access_token=${token}&include=${include}${localeParam}`;
56	};
57	
58	export const resolveLinkedAssets = <T extends ContentfulRawEntry>(
59	  item: T,
60	  includes?: ContentfulEntriesResponse['includes'],
61	  visitedIds: Set<string> = new Set(),
62	): T => {
63	  // Guard against cyclic entry graphs (A → B → A). Contentful's include=2 limit controls
64	  // response depth but does not prevent cycles in the returned data.
65	  if (visitedIds.has(item.sys.id)) return item;
66	  const nextVisited = new Set(visitedIds).add(item.sys.id);
67	
68	  // Clone fields too, not just the top-level item — a shallow `{ ...item }` still shares the
69	  // same `fields` object reference with the original, so writing into resolvedItem.fields
70	  // below would otherwise mutate the raw Contentful response entry in place.
71	  const resolvedItem = { ...item, fields: { ...item.fields } };
72	  if (item.fields) {
73	    Object.keys(item.fields).forEach((fieldKey) => {
74	      const fieldValue = item.fields[fieldKey] as ContentfulLink;
75	      if (fieldValue?.sys?.type === 'Link') {
76	        if (fieldValue.sys.linkType === 'Asset') {
77	          const linked = includes?.Asset?.find((asset) => asset.sys.id === fieldValue.sys.id);
78	          if (linked) resolvedItem.fields[fieldKey] = linked;
79	        } else if (fieldValue.sys.linkType === 'Entry') {
80	          const linked = includes?.Entry?.find((entry) => entry.sys.id === fieldValue.sys.id);
81	          if (linked && !nextVisited.has(linked.sys.id)) {
82	            resolvedItem.fields[fieldKey] = resolveLinkedAssets(linked, includes, nextVisited);
83	          } else {
84	            // Delete for both unresolved links and cyclic entries — a cyclic entry returning
85	            // its own stub (the pre-cycle-check fallback) is as unsafe as an unresolved link.
86	            delete resolvedItem.fields[fieldKey];
87	          }
88	        }
89	      } else if (Array.isArray(fieldValue)) {
90	        // Resolve arrays of links (e.g. an `items` field holding multiple linked entries/assets).
91	        // Unresolved and cyclic Entry links are filtered out rather than returned as Link stubs —
92	        // a stub passing through the T[] cast is invisible to TypeScript but throws at runtime.
93	        resolvedItem.fields[fieldKey] = fieldValue
94	          .map((element) => {
95	            const el = element as ContentfulLink;
96	            if (el?.sys?.type === 'Link') {
97	              if (el.sys.linkType === 'Asset') {
98	                const linked = includes?.Asset?.find((asset) => asset.sys.id === el.sys.id);
99	                return linked ?? element;
100	              } else if (el.sys.linkType === 'Entry') {
101	                const linked = includes?.Entry?.find((entry) => entry.sys.id === el.sys.id);
102	                if (linked && !nextVisited.has(linked.sys.id)) {
103	                  return resolveLinkedAssets(linked, includes, nextVisited);
104	                }
105	                return null;
106	              }
107	            }
108	            return element;
109	          })
110	          .filter((el) => el !== null) as typeof fieldValue;
111	      }
112	    });
113	  }
114	  return resolvedItem;
115	};
